package com.atlasiq.security;
import com.atlasiq.persistence.*;import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class SbomService {private final AnalysisStore store;public SbomService(AnalysisStore s){store=s;}
 public Map<String,Object> cyclonedx(String id){QirModel m=model(id);List<Map<String,Object>> c=packages(m).stream().map(n->Map.<String,Object>of("type","library","bom-ref",n.id(),"name",n.name(),"version",String.valueOf(n.metadata().getOrDefault("version","unknown")),"purl",purl(n))).toList();return Map.of("bomFormat","CycloneDX","specVersion","1.6","version",1,"metadata",Map.of("component",Map.of("type","application","name",m.repository())),"components",c);}
 public Map<String,Object> spdx(String id){QirModel m=model(id);List<Map<String,Object>> p=packages(m).stream().map(n->Map.<String,Object>of("SPDXID","SPDXRef-"+safe(n.id()),"name",n.name(),"versionInfo",String.valueOf(n.metadata().getOrDefault("version","unknown")),"downloadLocation","NOASSERTION","licenseConcluded",String.valueOf(n.metadata().getOrDefault("license","NOASSERTION")))).toList();return Map.of("spdxVersion","SPDX-2.3","dataLicense","CC0-1.0","SPDXID","SPDXRef-DOCUMENT","name","AtlasIQ-"+m.repository(),"documentNamespace","https://atlasiq.dev/spdx/"+id,"packages",p);}
 private QirModel model(String id){return store.find(id).orElseThrow().model();}private List<QirNode> packages(QirModel m){return m.nodes().stream().filter(n->"software-package".equals(n.type())).toList();}private String safe(String x){return x.replaceAll("[^A-Za-z0-9.-]","-");}private String purl(QirNode n){String eco=String.valueOf(n.metadata().getOrDefault("ecosystem",n.technology()));String ver=String.valueOf(n.metadata().getOrDefault("version",""));return "pkg:"+eco+"/"+n.name()+(ver.isBlank()?"":"@"+ver);}
}